function intervalView(v){const out=[];let pos=0;for(const s of v.segments){if(s.startMs>pos)out.push({startMs:pos,endMs:s.startMs,status:'pending'});out.push({startMs:s.startMs,endMs:s.endMs,status:s.review.status,scene:s.review.status==='pending'?null:ALL_SCENES.find(x=>x.videoId===v.id&&x.id===s.id)});pos=s.endMs;}if(v.durationMs!==null&&pos<v.durationMs)out.push({startMs:pos,endMs:v.durationMs,status:'pending'});return out;}
function renderCoverage(v){$('#languageStatus').textContent=languageNote(v);$('#coverageTitle').textContent=v.title;$('#coverageState').textContent=statusLabel(v);$('#coverageNumbers').textContent=coverageText(v);$('#coverageSample').textContent=`프레임 기반 근사 구간 ${secLabel(v.coverage.sampledMs)} · 연속 검수 ${secLabel(v.coverage.verifiedMs)} · FX 연속 검수 ${secLabel(v.coverage.fxVerifiedMs||0)}`;
 const duration=v.durationMs;const intervals=intervalView(v);$('#coverageBar').innerHTML=duration!==null?intervals.map(x=>`<button type="button" class="coverage-span ${x.status}" style="width:${(x.endMs-x.startMs)/duration*100}%" ${x.scene?`data-select="${esc(x.scene.key)}"`:''} title="${fmt(x.startMs)}–${fmt(x.endMs)} · ${{classified:'검수 완료',sampled:'프레임 기반 검토',pending:'검수 대기'}[x.status]}" aria-label="${fmt(x.startMs)}–${fmt(x.endMs)} ${x.status==='classified'?'검수 완료':x.status==='sampled'?'프레임 기반 검토':'검수 대기'}"></button>`).join(''):'<div class="unknown-duration">전체 영상 길이를 확인한 뒤 0초부터 끝까지 표시합니다.</div>';
 $('#coverageRange').innerHTML=`<span class="mono">00:00</span><span class="mono">${duration===null?'전체 길이 미확인':fmt(duration)}</span>`;
 const gaps=v.coverage.unmappedRanges||[];$('#pendingRanges').innerHTML=duration===null?'<p>전체 길이를 아직 확인하지 못해 남은 구간 총량을 계산하지 않습니다.</p>':gaps.length?gaps.map(g=>`<p><span class="mono">${fmt(g.startMs)}–${fmt(g.endMs)}</span> · 분류 대기 (${secLabel(g.endMs-g.startMs)})</p>`).join(''):'<p>0초부터 끝까지 분류 구간이 이어집니다. 프레임 기반 검토에서는 구간 경계와 빠른 동작이 참고값일 수 있습니다.</p>'; const exactGaps=v.coverage.pendingRanges||[];$('#continuousRanges').innerHTML=duration===null?'<p>전체 길이 확인 전입니다.</p>':exactGaps.length?exactGaps.map(g=>`<p><span class="mono">${fmt(g.startMs)}–${fmt(g.endMs)}</span> · 연속 재생·경계 확인 대기</p>`).join(''):'<p>전구간 연속 검수 및 경계 확인이 완료됐습니다.</p>';
}
function renderNeutralPreview(){window.CutRadarEvidencePreview?.leave();window.CutRadarEpisodes?.leave();
 $('#sourceName').textContent='클립 미리보기';$('#sourceMeta').textContent='검색 결과에서 장면을 선택하세요';
 $('#sourceLink').hidden=true;$('#sourceLink').removeAttribute('href');$('#watchSelected').hidden=true;$('#watchSelected').removeAttribute('href');
 $('#previewSourceContext').hidden=true;$('#previewSourceName').textContent='';$('#previewSourceMeta').textContent='';
 window.ScenePlayback.reset();$('#screen').innerHTML='<div class="loadvideo preview-empty"><span class="play" aria-hidden="true">▷</span><span class="videolabel">먼저 장면을 선택해 주세요</span><span class="videotitle">선택한 장면을 여기서 확인합니다.</span></div>';
 $('#inspector').innerHTML='<div class="inspectmain"><div class="inspecttop"><span class="mono">CLIP PREVIEW</span></div><h1>검색 결과가 여기에 표시됩니다.</h1><p class="inspectsummary">검색 결과에서 장면을 선택하세요.</p></div>';
 $('#timeline').replaceChildren();$('#allTags').replaceChildren();$('#tagDetails').hidden=true;$('.coverage-panel').hidden=true;$('#reviewEvidence').textContent='';$('#fxEvidence').textContent='';
}
function renderViewer(preservePlayback=false){window.CutRadarEvidencePreview?.leave();window.CutRadarEpisodes?.leave();const s=currentScene();const v=videoById(s?.videoId||currentVideo);if(!v){renderNeutralPreview();return;}currentVideo=v.id;$('#sourceName').textContent='클립 미리보기';$('#sourceMeta').textContent='선택한 장면 미리보기';$('#previewSourceContext').hidden=false;$('#previewSourceName').textContent=v.title;$('#previewSourceMeta').textContent=(v.game?v.game+' · ':'')+'공식 원본 · 음성·자막 언어 미확인';$('#sourceLink').hidden=false;$('#watchSelected').hidden=false;$('.coverage-panel').hidden=false;$('#tagDetails').hidden=false;$('#sourceLink').href=v.officialUrl;$('#watchSelected').href=videoLink(v,s?.startMs||0);$('#watchSelected').textContent=youtubeId(v)?'YouTube에서 보기 ↗':'원본 영상 보기 ↗';
 $('#inspector').innerHTML=s?`<div class="inspectmain"><div class="inspecttop"><span class="mono">${s.referenceExclusion?'활용 제외':s.highlight?'HIGHLIGHT':'SCENE'} / ${s.review.status==='sampled'?'프레임 기반 검토':'검수 완료'}</span><span class="mono">${fmt(s.startMs)}–${fmt(s.endMs)}</span></div><h1>${esc(s.title)}</h1><p class="inspectsummary">${esc(s.summary)}</p>${s.referenceExclusion?`<p>레퍼런스 활용 제외: ${esc(s.referenceExclusion)} · 시간축 기록만 보존</p>`:''}</div>${s.highlight&&s.why===s.title&&s.use.every(x=>x==='동작·구도·FX 참고')?'<div class="insight"><p>하이라이트 선정 이유·활용 포인트 보완 중</p></div>':s.why?`<div class="insight"><div class="sectionlabel mono">01 / 눈여겨볼 이유</div><p>${esc(s.why)}</p></div>`:''}${s.use.length&&!s.use.every(x=>x==='동작·구도·FX 참고')?`<div class="insight"><div class="sectionlabel mono">02 / 참고할 포인트</div><ul class="usepoints">${s.use.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}`:`<div class="inspectmain"><div class="inspecttop"><span class="mono">PENDING</span><span>${v.durationMs===null?'길이 미확인':fmt(v.durationMs)}</span></div><h1>아직 분류하지 않은 영상</h1><p class="inspectsummary">${esc(v.title)}의 장면 내용은 확인 후 추가합니다. 대기 시간을 완료로 세지 않습니다.</p></div>`;
 $('#allTags').innerHTML=s?Object.entries(s.groups).map(([axis,tags])=>`<div class="alltaggroup"><h3>${axis}</h3><p>${tags.map(t=>`<button type="button" data-axis="${esc(axis)}" data-tag="${esc(t)}">${esc(t)}</button>`).join(' / ')}</p></div>`).join(''):'<p>아직 확인된 장면 태그가 없습니다.</p>';
 $('#tagDetailsTitle').textContent=s?`선택 장면의 전체 태그 / ${flatTags(s).length}개`:'선택 영상의 태그 / 분류 대기';
 $('#reviewEvidence').textContent=s?`확인 방식: ${s.review.method} · 경계: ${s.review.boundaryPrecision==='exact'?'정확':'참고값'} · 오디오: ${s.review.audioReviewed?'확인':'미확인'}. ${s.review.evidence}`:'장면 관찰 기록이 아직 등록되지 않았습니다.';
 $('#fxEvidence').textContent=s?.fxEvidence?`FX 관찰 근거: ${s.fxEvidence}${s.fxTechniqueNote?' · 기법 해석: '+s.fxTechniqueNote:''}`:'FX 태그는 화면에서 관찰한 색·형태·움직임을 뜻합니다. 엔진 구현 기법은 별도로 확인되지 않으면 추정하지 않습니다.'; if(!preservePlayback){ const yt=youtubeId(v);if(playerLoaded&&yt){window.CutRadarWorkspace?.showStep('preview',{focus:true});window.ScenePlayback.mount(yt,v.title,(s?.startMs||0)/1000,s?s.endMs/1000:null,{muted:true,loop:()=>$('#previewLoop').checked});}else{window.ScenePlayback.reset(yt?undefined:'이 영상은 외부 원본에서 재생해 주세요.');$('#screen').innerHTML=`<span class="screentime mono">${s?fmt(s.startMs)+' — '+fmt(s.endMs):'분류 대기'}</span>${yt?`<button type="button" class="loadvideo" id="loadVideo"><span class="play" aria-hidden="true">▷</span><span class="videolabel">선택 구간 재생</span><span class="videotitle">${fmt(s?.startMs||0)}부터</span></button>`:`<a class="loadvideo" href="${esc(v.officialUrl)}" target="_blank" rel="noopener noreferrer"><span class="play">↗</span><span class="videolabel">공식 영상 열기</span></a>`}`;}}
 $('#timeline').innerHTML=(scope==='all'?ALL_SCENES.filter(x=>x.videoId===v.id):ALL_SCENES.filter(scopeMatches)).map(x=>`<button type="button" class="segment mono" data-select="${esc(x.key)}" aria-pressed="${x.key===current}" aria-label="${esc(x.title)} 선택">${fmt(x.startMs)}<br>${x.referenceExclusion?'활용 제외':x.review.status==='sampled'?'프레임':x.highlight?'주목':'장면'}</button>`).join('');
 renderCoverage(v);document.querySelectorAll('.video-entry').forEach(b=>b.classList.toggle('current',b.dataset.video===v.id));}
function sceneDetailMarkup(s,v){return `<details class="scene-details" data-scene-details="${esc(s.key)}" ${rowDetailsOpen.has(s.key)?'open':''}><summary aria-expanded="${rowDetailsOpen.has(s.key)}">상세정보</summary><div class="scene-detail-body"><strong>${esc(s.title)}</strong><p>${esc(v.title)} · ${fmt(s.startMs)}–${fmt(s.endMs)}</p><p>${esc(s.summary)}</p><p><b>${s.review.status==='sampled'?'프레임 기반 검토':'검수 완료'}</b> · ${esc(s.review.method||'관찰 기록')} · 경계 ${s.review.boundaryPrecision==='exact'?'정확':'참고값'} · 오디오 ${s.review.audioReviewed?'확인':'미확인'} · 대사·사건 순서 일치 미검증</p><p>${esc(s.review.evidence||'')}</p>${s.why?`<p>눈여겨볼 이유: ${esc(s.why)}</p>`:''}${s.use?.length?`<p>참고 포인트: ${esc(s.use.join(' / '))}</p>`:''}${s.fxEvidence?`<p>FX 근거: ${esc(s.fxEvidence)}</p>`:''}</div></details>`;}
document.addEventListener('toggle',e=>{const node=e.target;if(!node.matches?.('[data-scene-details]'))return;node.open?rowDetailsOpen.add(node.dataset.sceneDetails):rowDetailsOpen.delete(node.dataset.sceneDetails);node.querySelector('summary')?.setAttribute('aria-expanded',String(node.open));},true);
const VIEW_MODE_KEY='cutradar_view_mode';
let viewMode='list';
try{const saved=localStorage.getItem(VIEW_MODE_KEY);if(saved==='grid'||saved==='list')viewMode=saved;}catch{}
function updateViewModeUI(){
 const isGrid=viewMode==='grid';
 $('#viewModeList')?.setAttribute('aria-pressed',String(!isGrid));
 $('#viewModeGrid')?.setAttribute('aria-pressed',String(isGrid));
 $('#cards')?.classList.toggle('is-grid',isGrid);
 $('#cards')?.classList.toggle('is-list',!isGrid);
}
function setViewMode(mode){
 const next=mode==='grid'?'grid':'list';
 if(next===viewMode&&$('#cards')?.classList.contains('is-'+next))return;
 viewMode=next;
 try{localStorage.setItem(VIEW_MODE_KEY,viewMode);}catch{}
 updateViewModeUI();
 const y=window.scrollY;
 render();
 try{window.scrollTo({top:y,behavior:'instant'});}catch{window.scrollTo(0,y);}
}
function renderGridCard(s){
 const recommendation=keywordRanks.get(s.key);
 const v=videoById(s.videoId)||{id:s.videoId,title:s.videoId,officialUrl:''},yt=youtubeId(v);
 const tags=[...(s.groups?.['극적 상황']||[]).slice(1),...(s.groups?.['감정·분위기']||[]).slice(0,2),...(s.groups?.['샷 크기']||[]),...(s.groups?.['사용 방식']||[])];
 const thumbUrl=yt?`https://i.ytimg.com/vi/${encodeURIComponent(yt)}/mqdefault.jpg`:'';
 return `<article class="scenerow grid-card ${s.key===current?'selected':''}" data-scene="${esc(s.key)}"><button type="button" class="scene-select grid-select" data-select="${esc(s.key)}" aria-label="${recommendation?`추천 ${recommendation}위 · `:''}${fmt(s.startMs)} ${esc(s.title)} 미리보기" aria-pressed="${s.key===current}"><span class="grid-thumb">${thumbUrl?`<img src="${thumbUrl}" alt="" loading="lazy" decoding="async" class="grid-img" onerror="this.style.display='none'">`:''}<span class="grid-placeholder" aria-hidden="true"><span class="grid-play-icon">▶</span></span><span class="grid-time mono">${fmt(s.startMs)}–${fmt(s.endMs)}</span>${s.highlight?'<span class="grid-badge">HIGHLIGHT</span>':''}<span class="preview-action grid-preview-action">▶ 미리보기${s.key===current?'<span class="preview-selected">선택됨</span>':''}</span></span><span class="grid-meta"><span class="rowvideo">${esc(v.title)}</span><span class="rowtitle">${recommendation?`<span class="keyword-rank" aria-label="추천 ${recommendation}위">${recommendation}위</span> `:''}${esc(s.title)}</span><span class="rowtags">${esc(tags.slice(0,3).join(' · '))}</span></span></button><a class="rowlink grid-link" href="${esc(videoLink(v,s.startMs))}" target="_blank" rel="noopener noreferrer" title="YouTube에서 보기" aria-label="${esc(s.title)} · YouTube에서 보기">↗</a></article>`;
}
function renderRow(s){const recommendation=keywordRanks.get(s.key),match=keywordMatches.get(s.key);const v=videoById(s.videoId),tags=[...(s.groups['극적 상황']||[]).slice(1),...(s.groups['감정·분위기']||[]).slice(0,2),...(s.groups['샷 크기']||[]),...(s.groups['사용 방식']||[])];return `<article class="scenerow ${s.key===current?'selected':''}" data-scene="${esc(s.key)}"><button type="button" class="scene-select" data-select="${esc(s.key)}" aria-label="${recommendation?`추천 ${recommendation}위 · `:''}${fmt(s.startMs)} ${esc(s.title)} 미리보기" aria-pressed="${s.key===current}"><span class="scenetime mono">${fmt(s.startMs)}–${fmt(s.endMs)}</span><span class="rowbody"><span class="preview-action">▶ 미리보기${s.key===current?'<span class="preview-selected">선택됨</span>':''}</span><span class="rowvideo">${esc(v.title)}</span><span class="rowtitle">${recommendation?`<span class="keyword-rank" aria-label="추천 ${recommendation}위">${recommendation}위</span>`:''}${esc(s.title)}</span>${recommendation?`<span class="keyword-evidence">${esc((match?.hits||[]).filter(h=>h.scope==='segment').slice(0,2).map(h=>`${h.label}: ${String(h.text||h.kind||'관찰 기록').slice(0,48)}`).join(' · '))}${match?.missing?.length?` · 미일치: ${esc(match.missing.slice(0,3).join(', '))}`:''}</span>`:''}<span class="rowtags">${esc(tags.slice(0,3).join(' · '))}</span></span></button><a class="rowlink" href="${esc(videoLink(v,s.startMs))}" target="_blank" rel="noopener noreferrer" title="YouTube에서 보기" aria-label="${esc(s.title)} · YouTube에서 보기">↗</a>${sceneDetailMarkup(s,v)}</article>`;}
function render(refreshViewer=false){clearTimeout(keywordSearchTimer);$('#cards').setAttribute('aria-busy','false');updateViewModeUI();const q=$('#query').value;const queryTokens=tokenize(q);const searchKey=JSON.stringify([q,scope,highlightsOnly,browseAll,[...selected].map(([k,v])=>[k,[...v]])]);if(searchKey!==lastSearchKey){resultLimit=100;lastSearchKey=searchKey;}let pool=SCENES.filter(scopeMatches);const hasIntent=queryTokens.length>0||selectedCount()>0||scope!=='all'||highlightsOnly||browseAll;const filteredPool=pool.filter(s=>(!highlightsOnly||s.highlight)&&categoryMatches(s));let result=[];keywordRanks=new Map();keywordMatches=new Map();let interpretation=null;
 if(hasIntent&&queryTokens.length&&window.KeywordSentenceSearch){if(keywordSearchCache?.key!==searchKey)keywordSearchCache={key:searchKey,value:window.KeywordSentenceSearch.search(q,filteredPool)};interpretation=keywordSearchCache.value;const ranked=interpretation.results||[],recommended=interpretation.recommendations||[];keywordMatches=new Map(ranked.map(r=>[r.scene.key,r]));keywordRanks=new Map(recommended.map((r,i)=>[r.scene.key,i+1]));const pinned=new Set(keywordRanks.keys());result=[...recommended.map(r=>r.scene),...ranked.filter(r=>!pinned.has(r.scene.key)).map(r=>r.scene)];}
 else if(hasIntent)result=filteredPool.filter(s=>sceneMatchesTokens(s,queryTokens));
 const extracted=interpretation?.keywords||[],excluded=interpretation?.excluded||[];queryInterpretation.hidden=!interpretation||(!extracted.length&&!excluded.length&&!interpretation.reason&&!interpretation.unsupported?.length);queryInterpretation.textContent=interpretation?[extracted.length?'찾은 키워드: '+extracted.join(' · '):'',excluded.length?'제외: '+excluded.join(' · '):'',interpretation.reason||'',interpretation.unsupported?.length?'검색에 반영하지 못한 표현: '+interpretation.unsupported.join(' · '):'',keywordRanks.size?'위쪽 '+keywordRanks.size+'개는 관찰 근거가 있는 추천 후보입니다.':''].filter(Boolean).join(' / '):'';
 $('#selectionNotice').hidden=!hasIntent||!current||result.some(s=>s.key===current);$('#resultCount').textContent=!hasIntent?'검색 결과 대기':`${browseAll?'전체 장면':'검색 결과'} ${result.length.toLocaleString()}개`;$('#listScope').textContent=!hasIntent?`등록 장면 ${SCENES.length.toLocaleString()}개 · 검색 전`:browseAll?'요청한 전체 장면 보기':scope==='all'?'등록 영상 전체에서 검색':scope.startsWith('game:')?scope.slice(5)+' 작품에서 검색':videoById(scope).title;$('#browseAllScenes').setAttribute('aria-pressed',String(browseAll));$('#browseAllScenes').textContent=browseAll?'전체 장면 접기':'전체 장면 보기';$('#clearSearch').hidden=!q;$('#resetFilters').disabled=!selectedCount();$('#activeFilters').innerHTML=(queryTokens.length?`<button type="button" data-clear-query aria-label="입력 검색어 해제">검색: ${esc(q)} ×</button>`:'')+(highlightsOnly?'<button type="button" data-clear-highlight>하이라이트만 ×</button>':'')+[...selected].flatMap(([axis,tags])=>[...tags].map(t=>`<button type="button" data-axis="${esc(axis)}" data-tag="${esc(t)}" aria-label="${esc(axis)} ${esc(t)} 필터 해제">${esc(axis)}: ${esc(t)} ×</button>`)).join('');
 $('#cards').innerHTML=!hasIntent?'<div class="empty search-idle"><h3>검색 결과가 여기에 표시됩니다.</h3><p>검색어 또는 필터를 선택하세요.</p><div class="search-idle-examples"><button type="button" data-query="장병기 + 내려찍기">장병기 + 내려찍기</button><button type="button" data-query="클로즈업 + 긴장">클로즈업 + 긴장</button></div></div>':result.length?result.slice(0,resultLimit).map(viewMode==='grid'?renderGridCard:renderRow).join(''):`<div class="empty"><h3>${pool.length?'조건에 맞는 분류 장면이 없습니다.':'아직 분류 장면이 등록되지 않았습니다.'}</h3><p>미분류 구간은 검색 결과나 완료 수에 포함하지 않습니다.</p><button type="button" id="resetAll">검색과 필터 초기화</button></div>`;$('#moreResults').hidden=result.length<=resultLimit;$('#moreResults').textContent=`더 보기 (${Math.min(resultLimit,result.length)} / ${result.length}개 표시)`;document.querySelectorAll('.filtertag').forEach(b=>b.setAttribute('aria-pressed',String(isSelected(b.dataset.axis,b.dataset.tag))));$('#highlightToggle').setAttribute('aria-pressed',String(highlightsOnly));$('#highlightToggle').textContent=highlightsOnly?'하이라이트만':'전체 분류';if(refreshViewer)renderViewer();window.CutRadarFineSearch?.render();}
function searchNow(e){if(e)e.preventDefault();clearTimeout(keywordSearchTimer);browseAll=false;if(e?.type==='input'&&window.KeywordSentenceSearch&&$('#query').value.trim()){queryInterpretation.hidden=false;queryInterpretation.textContent='검색어를 정리하고 있습니다…';$('#cards').setAttribute('aria-busy','true');if(e.isComposing)return;keywordSearchTimer=setTimeout(()=>render(),180);return;}render();}
function resetConditions(){window.CutRadarFineSearch?.clear();selected.clear();$('#query').value='';highlightsOnly=false;browseAll=false;scope='all';$('#videoScope').value='all';renderFacets();render();}
