$('#moreResults').addEventListener('click',()=>{resultLimit+=100;render();});$('#searchForm').addEventListener('submit',e=>{if(window.innerWidth<=900)$('#query')?.blur();searchNow(e);});$('#query').addEventListener('keydown',e=>{if(e.key==='Enter'&&window.innerWidth<=900)$('#query')?.blur();});['input','change','search','compositionend'].forEach(event=>$('#query').addEventListener(event,searchNow));$('#clearSearch').addEventListener('click',()=>{browseAll=false;$('#query').value='';render();$('#query').focus();});$('#resetFilters').addEventListener('click',()=>{browseAll=false;selected.clear();render();});$('#videoScope').addEventListener('change',()=>{browseAll=false;scope=$('#videoScope').value;window.CutRadarFineSearch?.clear();selected.clear();renderFacets();render();});$('#clearConditions').addEventListener('click',resetConditions);$('#highlightToggle').addEventListener('click',()=>{browseAll=false;highlightsOnly=!highlightsOnly;render();});$('#viewModeList')?.addEventListener('click',()=>setViewMode('list'));$('#viewModeGrid')?.addEventListener('click',()=>setViewMode('grid'));$('#mobileFilter').addEventListener('click',()=>{const open=$('#filters').classList.toggle('open');$('#mobileFilter').setAttribute('aria-expanded',String(open));$('#mobileFilter').textContent=open?'필터 −':'필터 +';});
