function validate(doc){if(doc?.format!=='cut-radar-edit'||doc.version!==1||!Array.isArray(doc.clips)||doc.clips.length>300)throw Error('지원하지 않는 편집본입니다.');return doc.clips.map(c=>{const s=SCENES.find(s=>s.key===c.sceneKey),v=s&&videoById(s.videoId);if(!s||c.videoId!==v.id)throw Error('현재 목록에 없는 장면입니다.');if(!Number.isFinite(c.inMs)||!Number.isFinite(c.outMs)||c.inMs<0||c.outMs-c.inMs<100||c.outMs>(v.durationMs||s.endMs)||!rates.includes(c.rate))throw Error('시간·배속 범위를 확인하세요.');return {id:uid(),sceneKey:s.key,videoId:v.id,youtubeId:youtubeId(v)||null,title:s.title,inMs:Math.round(c.inMs),outMs:Math.round(c.outMs),rate:c.rate,reviewedInMs:s.startMs,reviewedOutMs:s.endMs};});}
function manifest(){return {format:'cut-radar-edit',version:1,title:'CUT RADAR 레퍼런스 애니메틱',clips:clips.map(c=>({...c}))};}
// Clip IDs are runtime identities, not project content. Order and all saved fields matter.
function contentKey(list=clips){return JSON.stringify(list.map(({id,...clip})=>Object.fromEntries(Object.entries(clip).sort(([a],[b])=>a.localeCompare(b)))));}
function hasUnsavedChanges(){return contentKey()!==savedContent;}
