 if(!source)return;stop();const c={...source},v=videoById(c.videoId),yt=youtubeId(v);window.SceneReferenceContext?.show(c.sceneKey,c.inMs);setSource(c.sceneKey,c.inMs,c.outMs);if(!yt){say('이 영상은 원본 링크 또는 오프라인 렌더로 확인하세요.');return;}
