function play(i,sequence=true){if(clips[i]&&window.CutRadarWorkspace?.isMobile()&&document.querySelector('.cut-workspace')?.dataset.step!=='edit')window.CutRadarWorkspace.showStep('preview');if(!clips[i]){stop();render();say('전체 미리보기가 끝났습니다.');return;}stop();active=i;const c=clips[i],v=videoById(c.videoId);window.SceneReferenceContext?.show(c.sceneKey,c.inMs);setSource(c.sceneKey,c.inMs,c.outMs);if(!c.youtubeId){say('YouTube 미리보기가 없는 컷입니다. 원본 파일 렌더를 이용하세요.');render();return;}playing=sequence;loading=true;requestedRate=c.rate;render();say(`${i+1}/${clips.length} 컷 연결 중…`);document.querySelector('.viewer').scrollIntoView({behavior:'auto',block:'start'});window.ScenePlayback.mount(c.youtubeId,v.title,c.inMs/1000,c.outMs/1000,{rate:c.rate,...statusCallbacks({onTiming:reportTiming,onBuffering:buffering=>{if(buffering)say(`${i+1}/${clips.length} 컷 · YouTube 버퍼링 중…`);},onVisibilityPause:visibilityPause,onReady:(actual,info)=>{loading=false;if(info?.pending)say(`${i+1}/${clips.length} 컷 · ${requestedRate}× 변경 요청 중, 현재 ${actual}×`);else if(info?.supported===false)say(`이 영상은 ${requestedRate}× 미지원 · 미리보기는 ${actual}×, 편집표 배속은 유지됩니다.`);else say(`${i+1}/${clips.length} 컷 미리보기 · 현재 ${actual}×`);},onRateChange:actual=>say(actual===requestedRate?`${i+1}/${clips.length} 컷 · ${actual}× 재생`:`${i+1}/${clips.length} 컷 · 재생 ${actual}× / 편집 설정 ${requestedRate}×`),onBlocked:()=>say('자동 재생이 차단되었습니다. 영상 또는 기존 플레이어의 재생 버튼을 눌러 주세요.'),onInterrupt:()=>{playing=false;loading=false;say('미리보기가 중단되었습니다. 재생 버튼으로 다시 시작할 수 있습니다.');},onProgress:time=>{const before=clips.slice(0,i).reduce((n,x)=>n+duration(x),0),elapsed=before+Math.max(0,Math.min(c.outMs-c.inMs,time*1000-c.inMs))/c.rate;get('editDuration').textContent=(elapsed/1000).toFixed(1)+' / '+(clips.reduce((n,x)=>n+duration(x),0)/1000).toFixed(1)+'초';},onEnd:()=>{loading=false;if(playing)play(active+1,true);else say(`${i+1}/${clips.length} 컷 · 선택 구간 미리보기가 끝났습니다.`);},onError:()=>{stop();say('재생할 수 없는 컷입니다. 다음 컷을 누르거나 원본 파일을 확인하세요.');}})});}
