host.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;const card=t.closest('[data-clip]'),i=Number(card?.dataset.clip);if(t.dataset.preview!==undefined){play(Number(t.dataset.preview),false);return;}if(t.dataset.move!==undefined){const j=Number(t.dataset.move);if(j<0||j>=clips.length)return;snapshot();[clips[i],clips[j]]=[clips[j],clips[i]];active=j;render();say(`${j+1}번 위치로 컷을 옮겼습니다.`);setTimeout(()=>{const targetCard=host.querySelector(`[data-clip="${j}"]`);const targetBtn=targetCard?.querySelector(j<i?'[data-move]:first-child':'[data-move]:nth-child(2)');if(targetBtn&&!targetBtn.disabled)targetBtn.focus({preventScroll:true});else targetCard?.querySelector('.edit-number')?.focus({preventScroll:true});},0);return;}if(t.dataset.copy!==undefined){if(clips.length>=300){say('최대 300컷까지 추가할 수 있습니다.');return;}snapshot();clips.splice(i+1,0,{...clips[i],id:uid()});render();return;}if(t.dataset.remove!==undefined){snapshot();clips.splice(i,1);active=-1;render();return;}switch(t.dataset.edit){case'play':play(active<0?0:active,true);break;case'pause':stop();say('일시정지됨 · 전체 미리보기는 현재 컷 시작부터 다시 연결합니다.');break;case'next':play(active+1,playing);break;case'undo':if(undo.length){stop();clips=JSON.parse(undo.pop());active=-1;render();}break;case'save':download('json',JSON.stringify(manifest(),null,2),'application/json');savedContent=contentKey();say('편집본 파일 다운로드를 요청했습니다. 브라우저에서 저장 완료를 확인하세요.');break;case'load':importRequest++;get('editImport').value='';get('editImport').click();break;case'csv':download('csv','\uFEFF'+['order,videoId,youtubeId,inMs,outMs,rate,outputDurationMs,title',...clips.map((c,i)=>[i+1,c.videoId,c.youtubeId,c.inMs,c.outMs,c.rate,Math.round(duration(c)),c.title].map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(','))].join('\n'),'text/csv');break;case'forget':get('editPersist').checked=false;try{localStorage.removeItem(key);}catch{}say('기기 저장본을 지웠습니다. 현재 편집은 유지됩니다.');}});
