host.addEventListener('change',e=>{const f=e.target.dataset.field;if(!f)return;const i=Number(e.target.closest('[data-clip]').dataset.clip),c=clips[i],v=videoById(c.videoId),n=Number(e.target.value)*(f==='rate'?1:1000);if(!Number.isFinite(n)||(f==='rate'&&!rates.includes(n))){render();return;}snapshot();if(f==='rate')c.rate=n;else if(f==='inMs')c.inMs=Math.round(Math.max(0,Math.min(n,c.outMs-100)));else c.outMs=Math.round(Math.max(c.inMs+100,Math.min(n,v.durationMs||c.reviewedOutMs)));render();say('컷 수정됨 · 최소 0.1초, 영상 길이 안으로 보정됩니다.');});
