 function position(x,y){const rect=menu.getBoundingClientRect(),pad=8,w=innerWidth,h=innerHeight;menu.style.left=Math.max(pad,Math.min(x,w-rect.width-pad))+'px';menu.style.top=Math.max(pad,Math.min(y,h-rect.height-pad))+'px';}
 function open(block,x,y){const list=api.manifest().clips,id=block.dataset.clipId,index=list.findIndex(c=>c.id===id);if(index<0)return;close(false);targetId=id;lastIndex=index;origin=block;const c=list[index];menu.setAttribute('aria-label',`${index+1}번 컷 ${c.title} 편집`);menu.innerHTML=`<div class="edit-menu-heading">${index+1}번 컷 · ${String(c.title).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</div><button type="button" role="menuitem" data-menu-action="preview">▷ 이 컷 미리보기</button><button type="button" role="menuitem" data-menu-action="edit">길이·구간 편집</button><button type="button" role="menuitem" data-menu-action="rates" aria-haspopup="menu" aria-expanded="false">배속 ${c.rate}× <span>›</span></button><div id="editRateMenu" role="menu" aria-label="컷 배속" hidden>${rates.map(r=>`<button type="button" role="menuitemradio" aria-checked="${r===c.rate}" data-menu-rate="${r}">${r}×${r===c.rate?' ✓':''}</button>`).join('')}</div><div class="edit-menu-separator" role="separator"></div><button type="button" role="menuitem" data-menu-action="duplicate" ${list.length>=300?'disabled':''}>복제</button><button type="button" role="menuitem" data-menu-action="earlier" ${index===0?'disabled':''}>앞으로 이동</button><button type="button" role="menuitem" data-menu-action="later" ${index===list.length-1?'disabled':''}>뒤로 이동</button><button type="button" role="menuitem" data-menu-action="remove" class="edit-menu-remove">삭제</button><div class="edit-menu-separator" role="separator"></div><button type="button" role="menuitem" data-menu-action="undo" ${api.canUndo?.()?'':'disabled'}>되돌리기</button>`;menu.hidden=false;block.querySelector('[data-clip-menu]')?.setAttribute('aria-expanded','true');position(x,y);focusItem(items()[0]);}
